export const STATUS={new:'Novo',contacted:'Contatado',replied:'Respondeu',followup:'Follow-up',discarded:'Descartado'};
export const SITE={missing:'Não informado',social:'Só redes sociais',platform:'Plataforma externa',own:'Site próprio',review:'Verificar link'};
export const NICHES={aesthetics:'Clínicas de estética',real_estate:'Imobiliárias',health:'Saúde e clínicas',beauty:'Beleza',food:'Alimentação',services:'Serviços profissionais',retail:'Comércio',other:'Outros'};
export const COUNTRIES={BR:'Brasil',PT:'Portugal',ES:'Espanha',IT:'Itália',GB:'Reino Unido',DE:'Alemanha',NL:'Países Baixos',IE:'Irlanda',CH:'Suíça',AT:'Áustria'};
export const COUNTRY_FLAGS={BR:'🇧🇷',PT:'🇵🇹',ES:'🇪🇸',IT:'🇮🇹',GB:'🇬🇧',DE:'🇩🇪',NL:'🇳🇱',IE:'🇮🇪',CH:'🇨🇭',AT:'🇦🇹'};
export const FIELDS={name:'Nome da empresa *',city:'Cidade',state:'Estado',address:'Endereço',phone:'Telefone',website:'Site / website',rating:'Nota Google',reviews:'Número de avaliações',category:'Categoria',maps_url:'Link do Maps',place_id:'Place ID',instagram:'Instagram',email:'E-mail'};
const ALIASES={name:['nome','name','title','nome da empresa','empresa','business name','company name'],city:['cidade','city','town'],state:['estado','state','uf'],address:['endereco','address','full address','street','formatted address'],phone:['telefone','phone','phone number','phone unformatted','telefone 1','celular','whatsapp'],website:['site','website','web site','url site','website url','site url'],rating:['nota','rating','total score','stars','nota google','avaliacao'],reviews:['avaliacoes','reviews','reviews count','review count','user ratings total','numero de avaliacoes'],category:['categoria','category','category name','categories','tipo'],maps_url:['maps','maps url','google maps url','google maps link','url','link do maps'],place_id:['place id','placeid','google place id'],instagram:['instagram','instagram url'],email:['email','e mail']};
export const norm=v=>String(v??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();
const nicheRules=[['aesthetics',['clinica de estetica','clinica estetica','estetica','harmonizacao facial','botox','preenchimento','depilacao a laser','laser estetico','spa','medicina estetica']],['real_estate',['imobiliaria','imoveis','corretor de imoveis','corretora de imoveis','corretor imobiliario','apartamento','loteamento','condominio','aluguel de imoveis','construtora','incorporadora','real estate']],['health',['clinica','hospital','dentista','odontologia','fisioterapia','psicologia','nutricao','medico','laboratorio','terapia','farmacia']],['beauty',['salao de beleza','salao','barbearia','barber','cabeleireiro','cabelo','manicure','nail','estudio de beleza']],['food',['restaurante','lanchonete','hamburguer','pizzaria','padaria','cafeteria','cafe','bar','churrascaria','comida','doceria','confeitaria','sorveteria']],['services',['advocacia','advogado','contabilidade','contador','consultoria','marketing','agencia','oficina','mecanica','eletrica','arquitetura','engenharia','academia','escola','curso','seguranca']],['retail',['loja','mercado','supermercado','papelaria','floricultura','pet shop','farmacia','autopecas','moveis','roupas','moda','varejo']]];
export function classifyNiche(lead){const text=norm([lead?.name,lead?.category,lead?.address,lead?.description].filter(Boolean).join(' '));for(const [slug,terms] of nicheRules)if(terms.some(term=>text.includes(term)))return slug;return 'other';}
export const digits=v=>String(v??'').replace(/\D/g,'');
export const escape=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function safeUrl(value){if(!value)return '';try{const s=String(value).trim();if(/^[a-z][a-z\d+.-]*:/i.test(s)&&!/^https?:/i.test(s))return '';const u=new URL(/^https?:\/\//i.test(s)?s:'https://'+s);return ['http:','https:'].includes(u.protocol)&&u.hostname.includes('.')&&!u.username&&!u.password?u.href:'';}catch{return '';}}
export function siteType(value){if(!String(value??'').trim())return 'missing';const url=safeUrl(value);if(!url)return 'review';const host=new URL(url).hostname.toLowerCase().replace(/^www\./,'');const matches=list=>list.some(d=>host===d||host.endsWith('.'+d));if(matches(['instagram.com','facebook.com','fb.com','tiktok.com','wa.me','whatsapp.com','linktr.ee']))return 'social';if(matches(['ifood.com.br','anota.ai','menu.com.vc','aiqfome.com','ubereats.com','rappi.com.br','google.com','google.com.br','business.site','maps.app.goo.gl']))return 'platform';return 'own';}
const DIAL_CODES={BR:'55',PT:'351',ES:'34',IT:'39',GB:'44',DE:'49',NL:'31',IE:'353',CH:'41',AT:'43'};
export const leadCountry=l=>COUNTRIES[l?.country_code]?l.country_code:'BR';
export function phoneNumber(value,country='BR'){let p=digits(value),dial=DIAL_CODES[country]||'';if(!p)return '';if(country==='BR'){if(p.length===10||p.length===11)p='55'+p;return /^55[1-9]\d(?:[2-5]\d{7}|9\d{8})$/.test(p)?p:'';}if(p.startsWith('00'))p=p.slice(2);if(!p.startsWith(dial))p=dial+p.replace(/^0+/,'');return p.length>=8&&p.length<=15?p:'';}
export function opportunity(l){return Math.min(100,(siteType(l.website)==='own'?5:siteType(l.website)==='review'?15:40)+(phoneNumber(l.phone,leadCountry(l))?20:0)+(Number(l.rating)>=4?20:Number(l.rating)>=3?10:0)+(Number(l.reviews)>=100?20:Number(l.reviews)>=20?10:0));}
export const oppLabel=l=>opportunity(l)>=75?'Alta':opportunity(l)>=45?'Média':'Baixa';
export function parseNumber(value){let s=String(value??'').trim().replace(/\s/g,'');if(!s)return null;if(s.includes(','))s=s.replace(/\./g,'').replace(',','.');const n=Number(s);return Number.isFinite(n)?n:null;}
export function autoMap(headers){return Object.fromEntries(Object.keys(FIELDS).map(k=>[k,headers.findIndex(h=>ALIASES[k].includes(norm(h)))]));}
export function toLead(row,mapping){const value=k=>mapping[k]>=0?String(row[mapping[k]]??'').trim():'';const l=Object.fromEntries(Object.keys(FIELDS).map(k=>[k,value(k)]));l.rating=parseNumber(l.rating);if(l.rating!==null&&(l.rating<0||l.rating>5))l.rating=null;const rv=String(l.reviews).replace(/[.,](?=\d{3}(?:\D|$))/g,'');l.reviews=parseNumber(rv);if(l.reviews!==null)l.reviews=Math.max(0,Math.floor(l.reviews));l.niche=classifyNiche(l);return l;}
export function businessKey(l){let key;if(l.place_id)key='place:'+l.place_id.trim();else{const name=norm(l.name),city=norm(l.city),address=norm(l.address);key=address?`address:${name}|${address}|${city}`:l.phone?`phone:${name}|${digits(l.phone)}|${city}`:`name:${name}|${city}`;}const country=leadCountry(l);return country==='BR'?key:`country:${country}|${key}`;}
export function sameCompany(a,b){if(leadCountry(a)!==leadCountry(b))return false;if(a.place_id&&b.place_id)return a.place_id.trim()===b.place_id.trim();if(businessKey(a)===businessKey(b))return true;if(norm(a.name)!==norm(b.name))return false;if(norm(a.city)&&norm(b.city)&&norm(a.city)!==norm(b.city))return false;if(norm(a.address)&&norm(b.address))return norm(a.address)===norm(b.address);const country=leadCountry(a);return !!phoneNumber(a.phone,country)&&phoneNumber(a.phone,country)===phoneNumber(b.phone,country);}
export function mergeCompany(existing,incoming){const out={...existing};for(const k of Object.keys(FIELDS)){const v=incoming[k];if(v!==''&&v!==null&&v!==undefined)out[k]=v;}out.country_code=leadCountry(incoming);out.niche=existing.niche||incoming.niche||classifyNiche(out);return out;}
export function planImport(rows,mapping,existing,country='BR'){let invalid=0,duplicates=0,updated=0;const prepared=[];for(const row of rows){const l={...toLead(row,mapping),country_code:COUNTRIES[country]?country:'BR'};if(!l.name){invalid++;continue;}const idx=prepared.findIndex(p=>sameCompany(p,l));if(idx>=0){prepared[idx]=mergeCompany(prepared[idx],l);duplicates++;}else prepared.push(l);}for(const l of prepared)if(existing.some(e=>sameCompany(e,l)))updated++;return {leads:prepared,invalid,duplicates,updated,created:prepared.length-updated};}
export function csvCell(v){let s=String(v??'');if(/^[\s]*[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';}
export function exportCsv(leads){const keys=['name','city','state','address','phone','website','rating','reviews','category','maps_url','place_id','instagram','email','status','notes','follow_up_at'];return '\uFEFF'+[keys.map(k=>csvCell(FIELDS[k]?.replace(' *','')||({status:'Status',notes:'Notas',follow_up_at:'Próximo contato'})[k])).join(';'),...leads.map(l=>keys.map(k=>csvCell(k==='status'?STATUS[l[k]]:l[k])).join(';'))].join('\r\n');}
export function isDue(l,now=new Date()){return l.status!=='discarded'&&!!l.follow_up_at&&new Date(l.follow_up_at)<=now;}
export function filterLeads(leads,f,view='all'){const q=norm(f.q);const nicheView=view.startsWith('niche:')?view.slice(6):'';return leads.filter(l=>(view==='all'&&l.status!=='discarded'||view==='favorites'&&l.favorite||view==='followup'&&(l.status==='followup'||l.follow_up_at&&l.status!=='discarded')||view===l.status||nicheView&&(l.niche||classifyNiche(l))===nicheView)&&(!f.country||leadCountry(l)===f.country)&&( !q||norm([l.name,l.city,l.address,l.phone,l.category,l.email].join(' ')).includes(q))&&(!f.city||l.city===f.city)&&(!f.status||l.status===f.status)&&(!f.site||(f.site==='without'?['missing','social','platform'].includes(siteType(l.website)):siteType(l.website)===f.site))&&(!f.contact||(f.contact==='yes'?!!phoneNumber(l.phone,leadCountry(l)):!phoneNumber(l.phone,leadCountry(l))))&&(!f.opp||oppLabel(l)===f.opp)&&(!f.niche||((l.niche||classifyNiche(l))===f.niche))&&(!f.due||isDue(l)));}
